import{_ as o,C as t,o as i,c as p,E as r,a2 as s}from"./chunks/framework.BOeh4kYD.js";const l="/joinwell52/assets/execution-facts-20260915/retry-after-error.figure.zh.svg",b=JSON.parse('{"title":"AI 报错了，为什么数据库反而多写了一条？","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"AI 报错了，为什么数据库反而多写了一条？","date":"2026-09-15","published_date":"2026-09-15","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"AI 报错了，为什么数据库反而多写了一条？","summary":"看到“提交失败”，再试一次就安全吗？我们让工具先写入、再报错，数据库里的记录揭开了一个容易被忽略的区别。","cover":"/assets/execution-facts-20260915/retry-after-error.cover-v1.png","language":"zh-CN","lifecycle":"Published","publication_authorized":true,"evidence_status":"固定源码有界实验；范围见正文","pageClass":"execution-facts-article"},"headers":[],"relativePath":"zh/engineering/2026-09-15-retry-after-error.md","filePath":"zh/engineering/2026-09-15-retry-after-error.md","lastUpdated":1789442662000}'),c={name:"zh/engineering/2026-09-15-retry-after-error.md"};function d(h,e,u,g,_,m){const a=t("ArticleCover"),n=t("ArticleTableScroll");return i(),p("div",null,[r(a,{image:"/assets/execution-facts-20260915/retry-after-error.cover-v1.png",kicker:"开源工程观察 · 实验研究",title:"AI 报错了，为什么数据库反而多写了一条？",summary:"看到“提交失败”，再试一次就安全吗？我们让工具先写入、再报错，数据库里的记录揭开了一个容易被忽略的区别。",version:"2026-09-15",languageHref:"/en/engineering/2026-09-15-retry-after-error",languageLabel:"English"}),r(n,{language:"zh"}),e[0]||(e[0]=s('<h1 id="ai-报错了-为什么数据库反而多写了一条" tabindex="-1">AI 报错了，为什么数据库反而多写了一条？ <a class="header-anchor" href="#ai-报错了-为什么数据库反而多写了一条" aria-label="Permalink to &quot;AI 报错了，为什么数据库反而多写了一条？&quot;">​</a></h1><p>如果页面提示“提交失败”，你会不会再点一次？</p><p>先想象一种情况：第一次提交其实已经保存成功，只是成功消息没有传回来。第二次点击，可能就会把同一件事再做一遍。</p><p>我们没有拿真实订单或付款做实验，而是用一个本地数据库，专门制造“已经写入，随后报错”的情况。结果比预想的还反常：<strong>外层只允许尝试一次，数据库里却多出了两条记录。</strong></p><p>这个数字把问题带到了眼前：一次失败，究竟意味着没有做成，还是做成了却没能正确回话？</p><h2 id="一次尝试-怎么会写两次" tabindex="-1">一次尝试，怎么会写两次？ <a class="header-anchor" href="#一次尝试-怎么会写两次" aria-label="Permalink to &quot;一次尝试，怎么会写两次？&quot;">​</a></h2><p>线索来自 Ritiky23 为 <a href="https://github.com/crewAIInc/crewAI/pull/7458" target="_blank" rel="noreferrer">CrewAI 提交的修复提案</a>。CrewAI 是帮助多个 AI 助手调用工具、协作完成工作的框架。</p><p>我们也在开发协作系统，因此关心它怎样处理失败后的再次尝试。工具的回应可以是错误，但它对文件、数据库或外部服务造成的变化，可能已经发生。这个来源提供了具体代码，可以直接数一数动作究竟发生了几次。</p><p>旧代码把“整理输入参数”和“执行工具”放进了同一段错误处理。如果这段代码出了问题，后备处理就会换用原始参数，再调用一次工具。</p><p>于是出现了错位：本来想照顾“参数没整理好”的情况，却也接住了“工具已经写入，随后才报错”的情况。后者不需要再整理参数，却也被调用了第二次。</p><p>候选修复把两步分开：整理参数出错时仍可后备处理，真正执行工具时的错误，不再触发这一次额外调用。</p><h2 id="把尝试次数和写入次数放在一起看" tabindex="-1">把尝试次数和写入次数放在一起看 <a class="header-anchor" href="#把尝试次数和写入次数放在一起看" aria-label="Permalink to &quot;把尝试次数和写入次数放在一起看&quot;">​</a></h2><p>我们让一个测试工具先向 SQLite 数据库写入并保存一条记录，然后故意报错。SQLite 可以把数据库保存在本地文件里，便于直接核对结果。</p><p>保留项目原始调用方法，给它同样的输入，前后得到这组结果：</p><table tabindex="0"><thead><tr><th>场景</th><th>原代码：调用次数 / 保存记录数</th><th>候选修复：调用次数 / 保存记录数</th></tr></thead><tbody><tr><td>保存后报错，最多尝试一次</td><td>2 / 2</td><td>1 / 1</td></tr><tr><td>保存后报错，最多尝试三次</td><td>6 / 6</td><td>3 / 3</td></tr><tr><td>正常成功，最多尝试三次</td><td>1 / 1</td><td>1 / 1</td></tr><tr><td>读取参数说明失败，但工具随后成功</td><td>1 / 1</td><td>1 / 1</td></tr></tbody></table><p>我们分别检查了等待工具返回、以及通过异步方式等待结果的两条实现，结果一致。</p><p>第一行说明，修复去掉了一次尝试里多出来的那次调用。第二行又提醒我们：<strong>允许尝试三次，修复后仍可能保存三条记录。</strong></p><p><img src="'+l+'" alt="已经保存的记录，不会因为随后报错自动消失"></p><p><em>图 1：保存记录与返回结果是两步。来源：本轮 crew.json 中的 SQLite 记录；六次减少到三次，并不意味着事情只做了一遍。</em></p><p>修复确实有效，但它解决的是一个具体的重复调用问题。要让一件业务即使被反复请求也只生效一次，还需要识别“这些请求其实是同一件事”，并能找到之前的结果。</p><h2 id="那就先查一查-还要看查到了什么" tabindex="-1">那就先查一查？还要看查到了什么 <a class="header-anchor" href="#那就先查一查-还要看查到了什么" aria-label="Permalink to &quot;那就先查一查？还要看查到了什么&quot;">​</a></h2><p>顺着这个结果，我们继续问：重新执行以前，先查询记录，是否就足够了？</p><p>另一个管理 AI 会话的应用 Orca 提供了相邻线索。brennanb2025 在<a href="https://github.com/stablyai/orca/pull/20723" target="_blank" rel="noreferrer">这份修复提案</a>中处理的是：恢复会话时，历史里没找到一条消息，能不能就认定它没送达？</p><p>我们给相关程序相同的空历史输入。原代码会判断“未送达”，候选代码则保留“还不能确定”。在另一组输入里，候选也不再根据恢复时拿到的拒绝记录，要求换一个新消息编号。</p><p>原因不难理解：查到“没有”之前，得先知道自己查的记录是否足以证明没有。<strong>没找到成功记录，可能是没有成功，也可能是这份记录本来就不完整。</strong></p><p>这里测的是程序如何解释输入，没有真的重发消息。它与前面的数据库实验共同提醒我们：报错和没查到记录，都不能单独充当“放心再做一次”的理由。</p><h2 id="不让它盲目重做-也不能让人一直等" tabindex="-1">不让它盲目重做，也不能让人一直等 <a class="header-anchor" href="#不让它盲目重做-也不能让人一直等" aria-label="Permalink to &quot;不让它盲目重做，也不能让人一直等&quot;">​</a></h2><p>保留“还不能确定”更诚实，却带来了新的使用问题：如果系统一直不知道结果，后面的工作怎么办？</p><p>这是本轮实验之后最值得继续研究的地方。下一步可以模拟：动作保存成功，回复丢失，程序随后重启。恢复以后，能否沿用同一个操作编号找到已有结果，而不是再写一条？如果找不到，怎样让用户核实或决定下一步？</p><p>这些场景还没有在本轮完整跑过，不能提前宣布“已经解决”。</p><p>对于开发者，需要回答的是：谁保存操作编号和最终结果，重启后还能不能查到？对于使用者，如果页面说失败、刷新后却发现已经成功，你希望它提供“查询这次提交”的入口，还是只留下一个“再试一次”按钮？</p><details><summary>两项实验分别验证了什么</summary><p>CrewAI 对照固定为 a328710 与 2ab3821。从原始源码提取完整 use/ause/_use/_ause 四个方法，保留控制流；工具选择、遥测、缓存和格式化等周边依赖使用替身。SQLite 文件写入和提交实际发生。四场景、同步/异步两路径、两个版本，共16条观察。没有运行完整 CrewAI 系统，也没有真实邮件、订单或付款。</p><p>Orca 对照固定为 742a7ad 与 e6f789b，加载完整生产模块及实际导入。五类消息与历史输入、五类结果处置输入，在两个版本共形成20条观察；两类输入组没有串成真实发送链。空历史测试同时设定边界一致且没有正在进行的轮次。带恢复标记的拒绝保持未确认，不请求新身份。</p><p>还有一个保留的限制：未带恢复标记、原因为 not_delivered 的合成拒绝输入，候选仍请求新身份；本轮未证明真实发送端会产生这个组合。原 PR 中关于拒绝原因限制、手机端和编排端的评审意见，也未由我们复现。保留未知后，等待能否最终解除同样尚未验证。</p><p><a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-15-execution-facts" target="_blank" rel="noreferrer">完整来源、输入、结果及复跑方法</a>。这些数据不代表线上事故频率，也未证明 CodeFlowMu 存在对应缺陷。</p></details>',32))])}const A=o(c,[["render",d]]);export{b as __pageData,A as default};
